"A patch bundle asked the patcher for something this build of the app does not have, so it was made for a different Morphe version. Update the source in Sources; if it still happens, report it with the log.": "Ein Patch-Bundle hat vom Patcher etwas verlangt, das diese App-Version nicht hat, daher wurde es für eine andere Morphe-Version erstellt. Aktualisiere die Quelle unter „Quellen“; tritt es weiter auf, melde es mit dem Protokoll.",
"A patch could not be applied. This usually means the patch does not fit this version of the app. Check the details below and the log.": "Ein Patch konnte nicht angewendet werden. Meist passt der Patch nicht zu dieser App-Version. Sieh dir die Details unten und das Protokoll an.",
"A patch source decides what ends up inside your patched apps. Only add sources you trust. It is downloaded now and listed under Sources.": "Eine Patch-Quelle bestimmt, was in deinen gepatchten Apps landet. Füge nur Quellen hinzu, denen du vertraust. Sie wird jetzt heruntergeladen und unter „Quellen“ aufgelistet.",
"A path exclusion keeps one file or folder, and everything inside it, out of the tools you pick.": "Ein Pfadausschluss hält eine Datei oder einen Ordner samt Inhalt aus den gewählten Werkzeugen heraus.",
"A persistent Shizuku shell: cd and exports stick. Type exit or tap Exit Rish to leave.": "Eine dauerhafte Shizuku-Shell: cd und exportierte Variablen bleiben erhalten. Geben Sie exit ein oder tippen Sie auf „Rish beenden“, um sie zu verlassen.",
"A phone cannot answer after a reboot, so the sheet says what to expect instead; if nothing happens within ten seconds it says so and shows what the command printed. Recovery and Bootloader land on screens with their own buttons: Reboot system now (recovery) or START (bootloader) brings Android back.": "Nach einem Neustart kann das Telefon nicht mehr antworten, deshalb sagt das Blatt stattdessen, was zu erwarten ist; passiert innerhalb von zehn Sekunden nichts, sagt es das und zeigt, was der Befehl ausgegeben hat. Recovery und Bootloader landen auf Bildschirmen mit eigenen Schaltflächen: Reboot system now (Recovery) oder START (Bootloader) bringt Android zurück.",
"A phone without zram, or one whose shell may not read the counters, shows Not available with the reason. The numbers are a snapshot; they move as apps run.": "Ein Telefon ohne zram, oder eines, dessen Shell die Zähler nicht lesen darf, zeigt „Nicht verfügbar“ mit dem Grund. Die Zahlen sind eine Momentaufnahme; sie ändern sich, während Apps laufen.",
"A remote address, SSE": "Eine Remote-Adresse, SSE",
"A remote address, streamable HTTP": "Eine Remote-Adresse, Streamable HTTP",
"A repository: the app will look for its catalog (index-v2.json or index-v1.jar).": "Ein Repository: Die App sucht dessen Katalog (index-v2.json oder index-v1.jar).",
"A row": "Eine Zeile",
"A saturated theme that uses a wide range of colors": "Ein gesättigtes Design mit einem breiten Farbspektrum",
"A search is still running": "Eine Suche läuft noch",
"A segment exclusion matches a name segment, like \"DCIM/Camera\", wherever it is.": "Ein Segmentausschluss passt auf ein Namenssegment wie „DCIM/Camera“, wo auch immer es steht.",
"A setting that is on or off": "Eine Einstellung, die an oder aus ist",
"A setting without a description": "Eine Einstellung ohne Beschreibung",
"A sheet with every action for that app: settings, launch, force stop, enable or disable, uninstall, suspend, permissions, activities. Choose which ones it lists in the Action Button card above.": "Ein Fenster mit allen Aktionen für diese App: Einstellungen, Starten, Beenden erzwingen, Aktivieren oder Deaktivieren, Deinstallieren, Pausieren, Berechtigungen, Activities. Welche es anzeigt, wählen Sie oben in der Karte „Aktionsschaltfläche“.",
"A short tick you feel when you tap": "Ein kurzes Ticken beim Tippen",
"A short vibration for every button, tab, switch and list row you tap. On by default. It is only the app's own tick: the phone's own touch feedback setting is not changed.": "Eine kurze Vibration bei jedem Tipp auf Schaltflächen, Tabs, Schalter und Listenzeilen. Standardmäßig an. Es ist nur das App-eigene Ticken: Die Touch-Feedback-Einstellung des Telefons bleibt unverändert.",
"A small knowledge graph the agent can read and write between turns.": "Ein kleiner Wissensgraph, den der Agent zwischen den Gesprächsrunden lesen und beschreiben kann.",
"A source is a bundle of patches. Turn a source off to keep it without using it: a source that is off is not loaded. More sources are in the Community tab.": "Eine Quelle ist ein Bündel von Patches. Schalte eine Quelle aus, um sie zu behalten, ohne sie zu nutzen: Eine ausgeschaltete Quelle wird nicht geladen. Weitere Quellen findest du im Tab „Community“.",
"A strong accent on a plain grey background.": "Ein kräftiger Akzent auf schlichtem grauem Hintergrund.",
"A strong accent that stands out against no background tint": "Ein kräftiger Akzent, der sich ohne Hintergrundtönung abhebt",
"A tab needs a name": "Ein Tab braucht einen Namen",
"A tab on the bottom bar": "Ein Tab in der unteren Leiste",
"A value can't contain a carriage return (use plain line breaks)": "Ein Wert darf keinen Wagenrücklauf (CR) enthalten (normale Zeilenumbrüche verwenden)",
"A value can't contain control characters": "Ein Wert darf keine Steuerzeichen enthalten",
"A value with several lines.": "Ein Wert mit mehreren Zeilen.",
"A web address or URI.": "Eine Webadresse oder URI.",
"A whole number.": "Eine ganze Zahl.",
"A working mode (ADB, Shizuku or root) is ready. Grant all remaining permissions with it now? The app restarts afterwards.": "Ein Betriebsmodus (ADB, Shizuku oder Root) ist bereit. Alle übrigen Berechtigungen jetzt damit gewähren? Die App startet danach neu.",
"A wrong value can make the device misbehave. Delete takes the setting away so the system falls back to its default.": "Ein falscher Wert kann zu Fehlfunktionen des Geräts führen. „Löschen“ entfernt die Einstellung, sodass das System auf den Standardwert zurückfällt.",
