"Adaptive brightness adjustment (-1 to 1)": "Anpassung der adaptiven Helligkeit (-1 bis 1)",
"Adaptive brightness bias": "Helligkeitsversatz",
"Adaptive brightness is off, so this has no effect until you turn it on.": "Die adaptive Helligkeit ist aus, deshalb wirkt das erst, wenn du sie einschaltest.",
"Adaptive brightness picks the screen brightness from the light sensor. This value (Android calls it screen_auto_brightness_adj, from −1 to 1) shifts every choice darker or brighter: 0 is neutral, +0.5 noticeably brighter, −0.5 noticeably darker. It is the same thing the brightness slider changes while adaptive brightness is on.": "Die adaptive Helligkeit wählt die Bildschirmhelligkeit nach dem Lichtsensor. Dieser Wert (Android nennt ihn screen_auto_brightness_adj, von −1 bis 1) verschiebt jede Wahl ins Dunklere oder Hellere: 0 ist neutral, +0,5 deutlich heller, −0,5 deutlich dunkler. Es ist dasselbe, was der Helligkeitsregler ändert, solange die adaptive Helligkeit an ist.",
"Adaptive off": "Adaptiv aus",
