"Adds a name and a value to one of the settings tables": "Fügt einer der Einstellungstabellen einen Namen und einen Wert hinzu",
"Adult filter: adult content": "Erwachsenenfilter: Inhalte für Erwachsene",
"Advanced": "Erweitert",
"Advanced mode: choose the patches. App-specific patches and universal patches are listed separately.": "Erweiterter Modus: Wähle die Patches. App-spezifische und universelle Patches werden getrennt aufgelistet.",
"Advertisement data": "Werbedaten",
"Affected paths": "Betroffene Pfade",
"Affected tools": "Betroffene Werkzeuge",
"After a successful install, ask whether to delete the installer file (it goes to a hidden folder first, with an Undo)": "Nach erfolgreicher Installation fragen, ob die Installationsdatei gelöscht werden soll (sie kommt zuerst in einen versteckten Ordner, mit Rückgängig)",
"After a test, the fastest service comes first. Off keeps the list in its usual order.": "Nach einem Test steht der schnellste Dienst oben. „Aus“ lässt die Liste in der üblichen Reihenfolge.",
"Agent websites": "Websites der Agenten",
"Agent when the app opens": "Agent beim Öffnen der App",
"Agents act through four kinds of steps: run a command, read a file, write a file, or edit part of a file. Before a command runs or a file changes you see exactly what, and choose Run (or Apply), Skip, or Always allow for the rest of the chat. Reading files in the current folder needs no OK.": "Agenten arbeiten mit vier Arten von Schritten: einen Befehl ausführen, eine Datei lesen, eine Datei schreiben oder einen Teil einer Datei bearbeiten. Bevor ein Befehl läuft oder sich eine Datei ändert, sehen Sie genau, was passiert, und wählen „Ausführen“ (oder „Anwenden“), „Überspringen“ oder „In diesem Chat immer zulassen“. Für das Lesen von Dateien im aktuellen Ordner ist keine Zustimmung nötig.",
"Agents can be wrong. Read what they want to run, especially with Working mode or Root, where a command can remove apps or change settings.": "Agenten können sich irren. Lesen Sie, was sie ausführen wollen, besonders im „Betriebsmodus“ oder mit Root, wo ein Befehl Apps entfernen oder Einstellungen ändern kann.",
"Agents only see what you send and what their steps return; keys and tokens in output are hidden from them.": "Agenten sehen nur, was Sie senden und was ihre Schritte zurückgeben; Schlüssel und Tokens in der Ausgabe bleiben ihnen verborgen.",
"Agents to add it to": "Agenten, zu denen es hinzugefügt wird",
"Airplane mode": "Flugmodus",
"Airplane mode off": "Flugmodus aus",
"Airplane mode on": "Flugmodus ein",
