"Also show only (combine as many as you like):": "Zusätzlich nur anzeigen (beliebig kombinierbar):",
"Also sources ~/.bashrc, so aliases and functions from your own Termux shell work here too. Turn off if yours does something unexpected for a non-interactive shell.": "Lädt außerdem ~/.bashrc, sodass auch Aliasse und Funktionen Ihrer eigenen Termux-Shell hier funktionieren. Ausschalten, wenn Ihre bei einer nicht interaktiven Shell etwas Unerwartetes tut.",
"Also target APK files that match the installed version. Disable to only remove older versions.": "Auch APK-Dateien erfassen, die zur installierten Version passen. Deaktivieren, um nur ältere Versionen zu entfernen.",
