"An app exclusion keeps one app out of the tools you pick (AppCleaner leaves its data alone, CorpseFinder does not call its folders remnants).": "Ein App-Ausschluss hält eine App aus den gewählten Werkzeugen heraus (AppCleaner lässt ihre Daten in Ruhe, CorpseFinder behandelt ihre Ordner nicht als Überreste).",
