"An area for the system to drop log files into.": "Ein Bereich, in dem das System Protokolldateien ablegt.",
"An excluded file, folder or app is skipped by the tools you choose, and nothing in an excluded folder is deleted. Exclude from a scan result with the Exclude button of a row.": "Eine ausgeschlossene Datei, ein Ordner oder eine App wird von den gewählten Werkzeugen übersprungen, und in einem ausgeschlossenen Ordner wird nichts gelöscht. Schließe aus einem Scanergebnis mit der Schaltfläche „Ausschließen“ einer Zeile aus.",
