"Android and apps then behave as if it was never set. It can be put back from the Undo bar or from Changes.": "Android und Apps verhalten sich dann so, als wäre die Einstellung nie gesetzt worden. Sie lässt sich über die Rückgängig-Leiste oder unter „Änderungen“ wiederherstellen.",
"Android asks whether this app may \"Run commands in Termux environment\".": "Android fragt, ob diese App die Berechtigung „Run commands in Termux environment“ erhalten darf.",
"Android blocks a few sensitive switches, Usage access among them, for an app installed from a file. This lifts the block (with appops through the working mode, or in this app's App info, in the three-dot menu).": "Android sperrt einige sensible Schalter, darunter den Zugriff auf Nutzungsdaten, für eine aus einer Datei installierte App. Dies hebt die Sperre auf (mit appops über den Betriebsmodus oder in der App-Info dieser App, im Drei-Punkte-Menü).",
"Android builds the palette from your home-screen wallpaper (what it does by default).": "Android erstellt die Palette aus dem Hintergrundbild Ihres Startbildschirms (Standardverhalten).",
"Android builds the whole palette from the color below.": "Android erstellt die gesamte Palette aus der Farbe unten.",
"Android can't verify this APK's signature (edited after signing, or unsigned).": "Android kann die Signatur dieses APK nicht überprüfen (nach dem Signieren bearbeitet oder nicht signiert).",
"Android can't verify this APK's signature (edited after signing, or unsigned). It is tried as it is first; if Android refuses it, a copy signed with this app's key is installed.": "Android kann die Signatur dieses APK nicht überprüfen (nach dem Signieren bearbeitet oder nicht signiert). Es wird zuerst unverändert versucht; lehnt Android es ab, wird eine mit dem Schlüssel dieser App signierte Kopie installiert.",
"Android closes its System UI process and starts it again at once: the status bar, the navigation bar and the lock screen vanish for about a second. Open apps stay open; the phone does not restart.": "Android beendet seinen System-UI-Prozess und startet ihn sofort neu: Statusleiste, Navigationsleiste und Sperrbildschirm verschwinden für etwa eine Sekunde. Offene Apps bleiben offen; das Telefon startet nicht neu.",
"Android did not keep the new value": "Android hat den neuen Wert nicht übernommen",
"Android documents most of its own settings, but phone makers and apps add many more. For those the editor says what the name and value suggest, as a guess. If you cannot tell what a setting does, leave it alone.": "Android dokumentiert die meisten eigenen Einstellungen, aber Hersteller und Apps fügen viele weitere hinzu. Für diese sagt der Editor, was Name und Wert vermuten lassen, als Schätzung. Wenn du nicht weißt, was eine Einstellung bewirkt, lass sie in Ruhe.",
"Android does not describe this setting.": "Android beschreibt diese Einstellung nicht.",
"Android is clearing the caches. This can take up to a minute or two; you can keep using the app.": "Android leert die Caches. Das kann bis zu ein oder zwei Minuten dauern; Sie können die App währenddessen weiter verwenden.",
"Android keeps its settings behind the shell. Connect one of them in Working Modes, then come back.": "Android hält seine Einstellungen hinter der Shell verborgen. Verbinden Sie unter „Betriebsmodi“ einen davon und kehren Sie dann zurück.",
"Android lists this overlay as unavailable": "Android führt dieses Overlay als nicht verfügbar auf",
"Android lists this overlay as unavailable (its target app is missing, or it is not approved), so it cannot be switched.": "Android führt dieses Overlay als nicht verfügbar auf (die Ziel-App fehlt oder es ist nicht freigegeben), daher lässt es sich nicht umschalten.",
"Android only uses a setting that something reads by that name. Leave the value empty to create it with nothing in it.": "Android nutzt eine Einstellung nur, wenn etwas sie unter diesem Namen ausliest. Lassen Sie den Wert leer, um sie ohne Inhalt anzulegen.",
"Android refused the request. Some phones (Xiaomi, Redmi, POCO) only allow it once \"USB debugging (Security settings)\" is on in Developer options, and some keys are locked by the system.": "Android hat die Anfrage abgelehnt. Manche Telefone (Xiaomi, Redmi, POCO) erlauben das erst, wenn in den Entwickleroptionen „USB-Debugging (Sicherheitseinstellungen)“ eingeschaltet ist, und manche Schlüssel sind vom System gesperrt.",
"Android refuses to install this over the app that is on the phone, because it is signed with another key. Uninstalling the installed copy removes its data too. Back up what you need first.": "Android verweigert die Installation über die vorhandene App, weil sie mit einem anderen Schlüssel signiert ist. Beim Deinstallieren der installierten Kopie werden auch ihre Daten gelöscht. Sichere vorher, was du brauchst.",
"Android refuses to install this over the app that is on the phone, because the patched app is signed with another key. Uninstalling the installed copy removes its data too. Back up what you need first.": "Android weigert sich, dies über die App auf dem Telefon zu installieren, weil die gepatchte App mit einem anderen Schlüssel signiert ist. Das Deinstallieren der installierten Kopie entfernt auch deren Daten. Sichere vorher, was du brauchst.",
"Android rejected that value for this setting. Try a value of the same kind as the current one.": "Android hat diesen Wert für diese Einstellung abgelehnt. Versuchen Sie einen Wert derselben Art wie den aktuellen.",
"Android repaints in a moment, and apps may restart.": "Android zeichnet die Oberfläche gleich neu, und Apps werden möglicherweise neu gestartet.",
"Android reports no signing certificate for this app.": "Android meldet kein Signaturzertifikat für diese App.",
"Android version": "Android-Version",
"Android versions": "Android-Versionen",
"Android will not ask again. Allow it by hand: App info of this app, Permissions, Additional permissions, Run commands in Termux environment.": "Android fragt nicht noch einmal. Erteilen Sie die Berechtigung manuell: App-Info dieser App, Berechtigungen, Zusätzliche Berechtigungen, „Run commands in Termux environment“.",
"Android will use your wallpaper’s colors with the Tonal Spot style again.": "Android verwendet wieder die Farben Ihres Hintergrundbilds mit dem Stil „Tonal Spot“.",
"Android’s hidden settings": "Versteckte Android-Einstellungen",
