"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner kann die Caches leeren, die kein Dateizugriff erreicht (die Schaltfläche „Cache leeren“ im Speicherbildschirm einer App), indem er für dich durch die Systemeinstellungen tippt. Dafür braucht er den Bedienungshilfen-Dienst dieser App. Der Dienst handelt nur, während AppCleaner Caches leert: Er öffnet nacheinander den App-Info-Bildschirm einer App nach der anderen, tippt auf „Cache leeren“ und hört auf, wenn der Bildschirm ausgeht oder sich sperrt. Eine Abdeckung über dem Bildschirm zeigt, was er tut, mit einer Möglichkeit zum Abbrechen. Nichts wird gelesen oder irgendwohin gesendet. Ab Android 13 braucht eine aus einer Datei installierte App eventuell zuerst „Eingeschränkte Einstellungen zulassen“ (App-Info dieser App, Menü mit den drei Punkten).",
