"Browser Use finished without an answer.": "Browser Use ist ohne Antwort fertig geworden.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use ist der Open-Source-Browser-Agent; dies ist seine gehostete Cloud, die für neue Konten eine kostenlose Stufe hat. Eine Ask-agent-Taste startet eine kurze Browser-Aufgabe, die die Frage im Web nachschlägt: Das kann ein oder zwei Minuten dauern und verbraucht etwas Guthaben. Es ist nur für die Ask-agent-Tasten da, kein Chat. Der Test des Schlüssels kostet nichts.",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use hat zu lange gebraucht (über 4 Minuten). Versuche es später erneut.",
"Browser Use was stopped before it had an answer.": "Browser Use wurde gestoppt, bevor es eine Antwort hatte.",
