"Choose how much Android limits the app while it is not in use. Active has no limits; restricted has the most.": "Lege fest, wie stark Android die App einschränkt, solange sie nicht benutzt wird. active hat keine Einschränkungen, restricted die meisten.",
"Choose package files": "Paketdateien auswählen",
"Choose something to send first": "Wählen Sie zuerst etwas zum Senden aus",
"Choose the APK to patch first": "Wähle zuerst die zu patchende APK",
"Choose the ones to send to the device": "Wählen Sie aus, was an das Gerät gesendet werden soll",
"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "Wählen Sie die Anmeldemethode im Verbindungsfenster des Agenten. Tools ohne Android-Build werden in eine Debian-Umgebung innerhalb von Termux installiert. Das dauert mehrere Minuten und braucht bis zu etwa 1 GB; die Anbieter unterstützen Android nicht offiziell, daher läuft ein Tool womöglich nicht auf jedem Telefon.",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "Wähle die Version und tippe auf ihre Download-Schaltfläche. Die Datei wird hier gespeichert und der Browser schließt sich von selbst.",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "Legen Sie fest, was die zusätzliche Schaltfläche in jeder Zeile der App-Liste tut. Sie ist immer ein Symbol; die Schaltflächen, die sich nach der App richten (Aktivieren / Deaktivieren, Installieren / Deinstallieren, Fortsetzen / Pausieren), wechseln Symbol und Aktion passend zum aktuellen Zustand der App.",
"Choose what the menu of each pinned tab lists and in what order. A menu lists four at most; the first one is the one under your thumb.": "Wähle, was das Menü jedes angehefteten Tabs auflistet und in welcher Reihenfolge. Ein Menü zeigt höchstens vier Einträge; der erste liegt unter deinem Daumen.",
"Choose what to install and which starter files to write": "Wähle, was installiert und welche Startdateien geschrieben werden sollen",
"Choosing a folder needs the app build": "Das Wählen eines Ordners braucht die App-Version",
"Choosing files works in the app": "Die Dateiauswahl funktioniert in der App",
