"Copilot needs a Copilot plan. GitHub retired GitHub Models in July 2026, so the Terminal uses GitHub's official Copilot CLI in Termux. Sign in there with GitHub, or save a fine-grained token with the \"Copilot Requests\" permission here and the CLI uses it.": "Copilot erfordert ein Copilot-Abo. GitHub hat GitHub Models im Juli 2026 eingestellt, daher nutzt das Terminal die offizielle Copilot CLI von GitHub in Termux. Melden Sie sich dort mit GitHub an oder speichern Sie hier ein Fine-grained-Token mit der Berechtigung „Copilot Requests“; die CLI verwendet es dann.",
