"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI hat dafür keine Antwort gefunden. Versuche die Websuche oder einen anderen Agenten.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI ist der Open-Source-Webcrawler; dies ist seine gehostete Cloud. Ein neues Konto bekommt kostenlose Credits und ein kostenloses Monatskontingent, ohne Karte. Eine Ask-agent-Taste schickt die Frage an seinen Antwortdienst, der das Web durchsucht, die Seiten liest und die Antwort schreibt. Es ist nur für die Ask-agent-Tasten da, kein Chat. Der Test verbraucht einen Credit.",
