"ESC": "ESC",
"EXPERT": "EXPERTE",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Jeder Agent speichert dies in seiner eigenen Datei, genau wie seine offizielle Anmeldung; so können zwei oder mehr Agenten denselben Server tragen und beide ihn nutzen. Codex speichert das Token eines Remote-Servers als Umgebungsvariable statt in seiner Datei. Nicht mit jeder Version jedes Tools getestet.",
"Each part between dots can be 63 characters at most.": "Jeder Teil zwischen den Punkten darf höchstens 63 Zeichen lang sein.",
"Each part between dots needs at least one character.": "Jeder Teil zwischen den Punkten braucht mindestens ein Zeichen.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Jede Shell hat ihren eigenen Bildschirm und bleibt geöffnet, während Sie andere Tabs nutzen: cd, export und Variablen bleiben von einem Befehl zum nächsten erhalten. „Shell neu starten“ startet eine neue.",
"Each wait is 600 seconds (10 minutes) at most.": "Jedes Warten dauert höchstens 600 Sekunden (10 Minuten).",
"Earlier certificates (the signing key was changed)": "Frühere Zertifikate (der Signaturschlüssel wurde geändert)",
"Edit": "Bearbeiten",
"Edit Saved List": "Gespeicherte Liste bearbeiten",
"Edit a file (if installed)": "Datei bearbeiten (falls installiert)",
"Edit a file (simple editor)": "Datei bearbeiten (einfacher Editor)",
"Edit as text": "Als Text bearbeiten",
"Edit exclusion": "Ausschluss bearbeiten",
"Edit saved command": "Gespeicherten Befehl bearbeiten",
"Edit text": "Text bearbeiten",
"Edited": "Bearbeitet",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "Das Bearbeiten eines APK ändert dessen Inhalt, daher passt die Signatur nicht mehr. Android installiert es erst, wenn es erneut signiert wurde: Verwenden Sie „Signieren“ (diese App signiert mit einem eigenen Schlüssel).",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "Das Bearbeiten eines APK ändert dessen Inhalt, daher passt die Signatur nicht mehr. Android installiert es erst, wenn es erneut signiert wurde; „Signieren“ erledigt das mit einem Schlüssel dieser App.",
"Effort": "Aufwand",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "Der Aufwand bewirkt nur bei Agenten etwas, deren eigene API diesen Regler hat (Claude, ChatGPT, Gemini, Grok); bei den anderen wird er gespeichert, hat aber beim Chatten per API-Schlüssel keine Wirkung, und keiner von ihnen gibt ihn an sein eigenes Anmeldetool in Termux weiter.",
"Emergency tone": "Notrufton",
"Empty": "Leer",
"Empty folder.": "Leerer Ordner.",
"Empty folders": "Leere Ordner",
"Empty folders from all over the device. Nested folders may require multiple passes.": "Leere Ordner auf dem ganzen Gerät. Verschachtelte Ordner brauchen eventuell mehrere Durchgänge.",
"Empty. What the tools delete is listed here.": "Leer. Hier steht, was die Werkzeuge löschen.",
