"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "Exa hat dazu keine Antwort gefunden. Versuche die Websuche oder einen anderen Agent.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa ist eine für KI gebaute Suchmaschine. Ihr Antwortdienst durchsucht das Web und schreibt eine kurze Antwort, die ihre Quellen nennt. Ein neues Konto erhält kostenlose Credits. Der Test des Schlüssels führt eine kleine Suche aus (einen Bruchteil eines Cents). Eine Ask-Agent-Schaltfläche schickt ihr die Frage; erst wenn du eine drückst, wird etwas gesendet.",
