"Format": "Format",
"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Gefunden durch Lesen der Klassennamen im Code der App auf diesem Telefon; nichts wird irgendwohin gesendet. Tracker-Liste: Exodus Privacy, lizenziert unter ODbL 1.0. Von einem Code-Shrinker (R8, ProGuard) umbenannter oder später nachgeladener Code kann einen Tracker verbergen, daher ist eine niedrige Zahl kein Beweis, dass es keine gibt.",
