"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "Jan führt KI-Modelle kostenlos auf Ihrem Computer aus. Am Computer: Jan, Einstellungen, Local API Server: Setzen Sie den Host auf 0.0.0.0 und starten Sie den Server, geben Sie dann hier die Adresse des Computers ein (etwa http://192.168.1.20:1337/v1). Eine Android-Version von Jan gibt es nicht.",
