"Lenovo": "Lenovo",
"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon ist ein persönlicher Open-Source-Assistent (Skills, Sprachsteuerung), der auf einem Computer mit Node.js und Python läuft. Es gibt keine Android-Version, und Leon ist kein Coding-Agent, daher chattet er nicht in diesem Terminal.",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "Termux Befehle von anderen Apps annehmen lassen",
"Let them act without asking": "Ohne Nachfrage handeln lassen",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "Erlaubt dem Agenten, Dateien unter dem am Ende des Befehls genannten Ordner zu lesen und zu schreiben (ändern Sie /sdcard nach Bedarf).",
"Lets the agent think in explicit steps before it acts.": "Lässt den Agenten in expliziten Schritten denken, bevor er handelt.",
"Lets this app change a few protected system settings used by some advanced features.": "Erlaubt dieser App, einige geschützte Systemeinstellungen zu ändern, die von manchen erweiterten Funktionen genutzt werden.",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "Erlaubt dieser App, die von Ihnen gewählten Paketdateien zu installieren, etwa APK-, APKS- und XAPK-Dateien aus Ihrem Speicher.",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "Erlaubt dieser App, den Bildschirm einer anderen App aus dem Hintergrund zu öffnen, etwa einer gerade installierten App.",
"Lets this app read the phone's own status reports (dumpsys), such as battery, power and memory details, without asking the shell each time. Granted through the working mode.": "Erlaubt dieser App, die Statusberichte des Telefons (dumpsys) zu lesen, etwa zu Akku, Energie und Speicher, ohne jedes Mal die Shell zu fragen. Wird über den Betriebsmodus erteilt.",
"Android's permission to read the system log (logcat) of every app. Live Logcat does not use it: it reads the log through the working mode. Granted through the working mode.": "Die Android-Berechtigung, das Systemprotokoll (logcat) aller Apps zu lesen. Live-Logcat nutzt sie nicht, sondern liest das Protokoll über den Betriebsmodus. Wird über den Betriebsmodus gewährt.",
"Lets this app show its notifications, such as the Wireless debugging pairing prompt and the progress of a long job.": "Erlaubt dieser App, ihre Benachrichtigungen anzuzeigen, etwa die Kopplungsaufforderung von Kabelloses Debugging und den Fortschritt eines langen Vorgangs.",
