"Measured against Cloudflare's public speed test servers (speed.cloudflare.com), at the data centre nearest to you. Cloudflare sees this phone's IP address, as any website does. The result is this phone, its radio and its network, not your plan's speed; Wi-Fi signal and other apps using the network change it.": "Gemessen mit den öffentlichen Speedtest-Servern von Cloudflare (speed.cloudflare.com), im Rechenzentrum, das Ihnen am nächsten liegt. Cloudflare sieht die IP-Adresse dieses Telefons, wie jede Website. Das Ergebnis zeigt dieses Telefon, sein Funkmodul und sein Netz, nicht die Geschwindigkeit Ihres Tarifs; das Wi-Fi-Signal und andere Apps, die das Netz nutzen, verändern es.",
