"Nothing changes until you tap Apply. The card reads the three scales back and shows what the phone really holds.": "Nichts ändert sich, bis du auf „Anwenden“ tippst. Die Karte liest die drei Skalen zurück und zeigt, was das Telefon wirklich hat.",
"Nothing changes until you tap Apply. The card reads the value back and shows what the phone really holds.": "Nichts ändert sich, bis du auf „Anwenden“ tippst. Die Karte liest den Wert zurück und zeigt, was das Telefon wirklich hat.",
"Nothing changes until you tap a service. The card reads the phone back and shows what it really holds.": "Nichts ändert sich, bis du einen Dienst antippst. Die Karte liest das Telefon zurück und zeigt, was es wirklich hat.",
"Nothing chosen yet.": "Noch nichts ausgewählt.",
"Nothing found.": "Nichts gefunden.",
"Nothing found. Both devices must be on the same Wi-Fi network, with wireless debugging on. You can also type the address by hand under Wi-Fi.": "Nichts gefunden. Beide Geräte müssen im selben Wi-Fi-Netzwerk sein und kabelloses Debugging aktiviert haben. Sie können die Adresse auch unter „Wi-Fi“ von Hand eingeben.",
"Nothing found. Keep the Wireless Debugging screen open and enter the ports manually.": "Nichts gefunden. Lassen Sie den Bildschirm „Kabelloses Debugging“ geöffnet und geben Sie die Ports manuell ein.",
"Nothing happened within 10 seconds, although the command reported no error: the mode could not do it.": "Innerhalb von 10 Sekunden ist nichts passiert, obwohl der Befehl keinen Fehler gemeldet hat: Der Modus konnte es nicht.",
"Nothing happened within 10 seconds: the mode could not do it.": "Innerhalb von 10 Sekunden ist nichts passiert: Der Modus konnte es nicht.",
"Nothing here was changed with this app yet.": "Hier wurde mit dieser App noch nichts geändert.",
"Nothing here was tested on every phone: when a step fails, the Terminal shows the exact error.": "Nichts hiervon wurde auf jedem Telefon getestet: Wenn ein Schritt fehlschlägt, zeigt das Terminal den genauen Fehler.",
"Nothing in the guide matches that. Try fewer or different words.": "Nichts in der Anleitung passt dazu. Versuchen Sie weniger oder andere Wörter.",
"Nothing inside.": "Nichts darin.",
"Nothing is selected": "Nichts ist ausgewählt",
"Nothing is swapped out right now.": "Gerade ist nichts ausgelagert.",
"Nothing matched. Try the package name, for example com.example.app.": "Keine Treffer. Versuche den Paketnamen, zum Beispiel com.example.app.",
"Nothing matches that filter.": "Nichts entspricht diesem Filter.",
