"Nothing runs until you confirm in the sheet. Power off, Bootloader and Recovery ask for a press-and-hold there.": "Nichts läuft, bis du im Blatt bestätigst. Ausschalten, Bootloader und Recovery verlangen dort ein Gedrückthalten.",
"Nothing runs until you confirm. After every action the section reads the phase back from the phone and shows that, not the command.": "Nichts läuft, bis du bestätigst. Nach jeder Aktion liest der Abschnitt die Phase vom Telefon zurück und zeigt sie, nicht den Befehl.",
