"Notifications": "Benachrichtigungen",
"Now:": "Jetzt:",
"Nubia": "Nubia",
"OBB resources": "OBB-Ressourcen",
"OEM": "OEM",
"OK": "OK",
"OPPO / realme App Market": "OPPO / realme App Market",
"Obtainium": "Obtainium",
"Off": "Aus",
"Off by default": "Standardmäßig aus",
"Off:": "Aus:",
"Off: reading outside the current folder needs your OK.": "Aus: Das Lesen außerhalb des aktuellen Ordners erfordert Ihre Zustimmung.",
"Off: the patches that work are applied and the failed ones are reported.": "Aus: Die Patches, die funktionieren, werden angewendet, und die fehlgeschlagenen werden gemeldet.",
"Offer to delete the file afterwards": "Anbieten, die Datei danach zu löschen",
"Official": "Offiziell",
"Official is the pre-installed source from the Morphe project. Custom is a source you added: its patches are code from whoever publishes it, and the app asks before it first loads a new or changed bundle.": "„Offiziell“ ist die vorinstallierte Quelle des Morphe-Projekts. „Eigene“ ist eine Quelle, die du hinzugefügt hast: Ihre Patches sind Code von dem, der sie veröffentlicht, und die App fragt, bevor sie ein neues oder geändertes Bündel zum ersten Mal lädt.",
"Offline cache": "Offline-Cache",
"Offline: showing what was loaded": "Offline: Es wird angezeigt, was geladen wurde",
"Old": "Alt",
"Older version": "Ältere Version",
"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (auf dem Gerät)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama läuft noch nicht auf diesem Telefon. Installieren Sie es unten oder geben Sie die Adresse eines Computers ein, auf dem es läuft.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama führt ein Coding-Modell direkt auf diesem Telefon aus: kostenlos und offline, sobald das Modell geladen ist. Es wird in Termux installiert; kleine Modelle (1,5B bis 3B) laufen auf einem Telefon am besten. Ollama auf einem Computer geht auch: Lassen Sie es dort auf allen Adressen lauschen und geben Sie hier die Adresse des Computers ein (z. B. 192.168.1.20:11434/v1).",
"On": "Ein",
"On battery": "Im Akkubetrieb",
"On device": "Auf dem Gerät",
"On the phone: not set (Android uses 1×)": "Auf dem Telefon: nicht gesetzt (Android nutzt 1×)",
"On the phone: not set (counts as 0)": "Auf dem Telefon: nicht gesetzt (zählt als 0)",
"On this phone": "Auf diesem Telefon",
"On:": "Ein:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Pro Shell läuft immer nur ein Befehl; lange Ausgaben werden auf dem Bildschirm und in dem, was ein Agent erhält, gekürzt.",
"One file only": "Nur eine Datei",
"One hue, five strengths: your color in full for the accent, at half and three quarters for the other accents, a fifth for the surfaces. From the 2026 Material color spec.": "Ein Farbton, fünf Stärken: Ihre Farbe voll für den Akzent, halb und zu drei Vierteln für die anderen Akzente, ein Fünftel für die Flächen. Aus der Material-Farbspezifikation 2026.",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Ein Schlüssel für die ganze App. Der Scan des Installers und der von Morphe Helper nutzen ihn beide; keiner fragt noch einmal danach, sie verweisen nur hierher, wenn er fehlt.",
"One more place to find apps": "Ein weiterer Ort, um Apps zu finden",
"One package per line. Duplicate entries are removed automatically. A name typed here is ticked above, and an app ticked above is added here.": "Ein Paket pro Zeile. Doppelte Einträge werden automatisch entfernt. Ein hier eingegebener Name wird oben angehakt, und eine oben angehakte App wird hier hinzugefügt.",
"One source color, ten ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Eine Quellfarbe, zehn Wege, daraus ein ganzes Design zu machen: Akzent, Hintergrund, Karten und Text, hell und dunkel. Ein Stil erstellt das Design aus der Quellfarbe unten.",
"Only Android restarts, not the phone: the screen goes black for a few seconds and every app closes, without the boot screen. Unsaved work in open apps is lost. Faster than a full reboot; it does not clear everything a full one does.": "Nur Android startet neu, nicht das Telefon: Der Bildschirm wird für ein paar Sekunden schwarz und jede App schließt, ohne Startbildschirm. Nicht gespeicherte Arbeit in offenen Apps geht verloren. Schneller als ein voller Neustart; es räumt nicht alles auf, was ein voller aufräumt.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Nur AppCleaner nutzt ihn: Er öffnet den App-Info-Bildschirm des Systems für jede App und tippt auf „Cache leeren“, für die Caches, die kein Dateizugriff erreicht. Er tut nichts anderes, liest außer diesen Bildschirmen nie, was auf dem Bildschirm steht, und hört auf, wenn der Bildschirm ausgeht.",
"Only Root may restart Android this way": "Nur Root darf Android so neu starten",
"Only Root may write /proc/sys/vm/drop_caches": "Nur Root darf /proc/sys/vm/drop_caches schreiben",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "In diese Dateien wird nur ein markierter Block geschrieben; was du darin hast, bleibt, und ein erneutes Ausführen aktualisiert den Block, statt einen weiteren hinzuzufügen.",
"Only a system app has updates to remove": "Nur bei einer System-App lassen sich Updates entfernen",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Füge nur Quellen hinzu, denen du vertraust. Eine Patch-Quelle bestimmt, was in deinen gepatchten Apps landet.",
"Only apps installed on this phone": "Nur auf diesem Telefon installierte Apps",
"Only base": "Nur Basis",
"Only hidden files are here.": "Hier gibt es nur versteckte Dateien.",
"Only include common media files, documents and archives.": "Nur gängige Mediendateien, Dokumente und Archive einbeziehen.",
"Only list what would run for each app. Nothing is run.": "Nur auflisten, was für jede App ausgeführt würde. Es wird nichts ausgeführt.",
"Only patches for apps installed on this phone": "Nur Patches für auf diesem Telefon installierte Apps",
"Only split bundles are listed for this app. Turn on Allow split APK.": "Für diese App sind nur Split-Bundles aufgeführt. Aktiviere Split-APK zulassen.",
"Only text and compiled XML files can be compared line by line": "Nur Text- und kompilierte XML-Dateien lassen sich zeilenweise vergleichen",
"Only the app name you typed is sent.": "Nur der eingegebene App-Name wird gesendet.",
"Only the lines written by the app you pick": "Nur die von der gewählten App geschriebenen Zeilen",
"Only the selected apps are saved.": "Nur die ausgewählten Apps werden gespeichert.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Nur der Text dieser App ändert sich; Namen, Pfade und Befehle in Codefeldern behalten ihre eigene Schriftart.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "Nur diese Beispielfrage wird an ihn gesendet: ob das Paket „Rechner“ deaktiviert werden kann.",
"Only values from −1 to 1 work here. Nothing was sent.": "Hier gehen nur Werte von −1 bis 1. Nichts wurde gesendet.",
