"Programs cannot read from the keyboard while they run, so full-screen programs (nano, vim, top, a Python prompt, the agents' own full-screen apps) are offered in a real Termux window instead: Open in Termux. In Termux, pkg and apt answer yes on their own.": "Programme können während der Ausführung nicht von der Tastatur lesen, daher werden Vollbildprogramme (nano, vim, top, eine Python-Konsole, die Vollbild-Apps der Agenten selbst) stattdessen in einem echten Termux-Fenster angeboten: „In Termux öffnen“. In Termux antworten pkg und apt von selbst mit Ja.",
