"Puts the phone into deep Doze now, as if it had lain still for an hour: background work and network pause for most apps.": "Versetzt das Telefon jetzt in tiefes Doze, als hätte es eine Stunde still gelegen: Hintergrundarbeit und Netzwerk pausieren für die meisten Apps.",
"Puts the phone into deep Doze right now, as if it had lain still for an hour: for most apps background work, network and alarms wait until the next maintenance window. The phone still rings. The forced Doze stays until you tap Wake device or the phone restarts.": "Versetzt das Telefon sofort in tiefes Doze, als hätte es eine Stunde still gelegen: Für die meisten Apps warten Hintergrundarbeit, Netzwerk und Alarme bis zum nächsten Wartungsfenster. Das Telefon klingelt weiterhin. Das erzwungene Doze bleibt, bis du „Gerät wecken“ antippst oder das Telefon neu startet.",
