"Temporary root is granted inside your root manager, such as KernelSU or APatch. Open it, allow this app Super User there, then come back and let the app switch to Root. If this app is not in its list (some root managers list an app only after it has asked for su), tap Request Super User first. Root Features unlock once su is granted.": "Temporärer Root wird in Ihrem Root-Manager gewährt, zum Beispiel KernelSU oder APatch. Öffnen Sie ihn, erlauben Sie dieser App dort Super User, kommen Sie dann zurück und lassen Sie die App zu Root wechseln. Steht diese App nicht in seiner Liste (manche Root-Manager führen eine App erst auf, nachdem sie su angefragt hat), tippen Sie zuerst auf „Superuser anfordern“. Die Root-Funktionen werden freigeschaltet, sobald su gewährt ist.",
