"The word": "Das Wort",
"The working mode changed meanwhile. The state above is what the phone reports now.": "Der Arbeitsmodus hat sich inzwischen geändert. Der Zustand oben ist, was das Telefon jetzt meldet.",
"The zram numbers are read again right after and the change is shown under each number.": "Die zram-Zahlen werden gleich danach erneut gelesen, und die Änderung wird unter jeder Zahl gezeigt.",
"Theater mode (watches)": "Theatermodus (Uhren)",
"Theme": "Design",
"Theme applied": "Design angewendet",
