"Theme style": "Designstil",
"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Erteilen Sie dieser App dann die Berechtigung „Run commands in Termux environment“ und testen Sie die Verbindung. Die Termux-Einrichtung in den Terminal-Einstellungen führt Sie durch die Schritte.",
"There are no saved lists to back up yet": "Es gibt noch keine gespeicherten Listen zum Sichern",
"There are no saved lists to back up yet; Restore works anyway.": "Es gibt noch keine gespeicherten Listen zum Sichern; Wiederherstellen funktioniert trotzdem.",
"There are no saved lists to share yet": "Es gibt noch keine gespeicherten Listen zum Teilen",
"There are no usable lists in that file.": "In dieser Datei gibt es keine verwendbaren Listen.",
"There is no key yet": "Es gibt noch keinen Schlüssel",
"There is no screen report yet": "Es gibt noch keinen Bildschirmbericht",
"There is no undo.": "Dies lässt sich nicht rückgängig machen.",
"There is nothing to delete. Scan first.": "Es gibt nichts zu löschen. Scanne zuerst.",
"These apps are currently selected for this action:": "Diese Apps sind derzeit für diese Aktion ausgewählt:",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Diese Apps sind deinstalliert, aber ihre Datenordner sind noch auf dem Telefon. Die Daten der angehakten Apps werden endgültig gelöscht.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Diese Apps sind deinstalliert. Ohne Root kann die App nicht sehen, welche davon noch Daten haben; alle zu leeren ist daher sicher, findet aber bei manchen vielleicht nichts. Die Daten der angehakten Apps werden endgültig gelöscht.",
"These apps were not checked, so an update for them may be waiting.": "Diese Apps wurden nicht geprüft, daher wartet für sie womöglich ein Update.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "Die Releases dieser Apps liegen auf Websites, die diese App nicht direkt prüfen kann. Obtainium kann sie verfolgen.",
"These are the three scales of Android’s Developer options: Window animation scale, Transition animation scale and Animator duration scale. Each multiplies how long its kind of animation takes.": "Das sind die drei Skalen aus Androids Entwickleroptionen: Fensteranimation, Übergangsanimation und Animator-Dauer. Jede vervielfacht, wie lange ihre Art von Animation dauert.",
"These files are too different to compare line by line. View each one instead.": "Diese Dateien unterscheiden sich zu stark für einen zeilenweisen Vergleich. Sehen Sie sich stattdessen jede einzeln an.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Sie laufen weiter, wenn der Browser geschlossen wird. „Pausieren“ behält, was heruntergeladen wurde, und „Fortsetzen“ fragt die Seite nur nach dem Rest (eine Seite, die das nicht kann, beginnt die Datei von vorn).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Sie werden übersprungen, es sei denn, du patchst trotzdem, was scheitern oder die App beschädigen kann.",
"Third-party packages only": "Nur Pakete von Drittanbietern",
"This Android version did not understand the command.": "Diese Android-Version hat den Befehl nicht verstanden.",
"This App's ADB Key": "ADB-Schlüssel dieser App",
"This Shizuku version is too old. Please update Shizuku.": "Diese Shizuku-Version ist zu alt. Bitte aktualisieren Sie Shizuku.",
"This action cannot be undone.": "Diese Aktion kann nicht rückgängig gemacht werden.",
"This action needs access to files on this phone.": "Diese Aktion erfordert Zugriff auf Dateien auf diesem Telefon.",
"This agent": "Dieser Agent",
"This agent has no sign-in tool": "Dieser Agent hat kein Anmeldetool",
"This app": "Diese App",
"This app (sandbox)": "Diese App (Sandbox)",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Diese App kann den Speicher nicht lesen. Erteile den Zugriff auf alle Dateien oder wähle eine Schriftdatei von Hand aus (dafür ist kein Zugriff nötig).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Diese App verlangt keinen bestimmten Touchscreen, keine bestimmte Tastatur und keine bestimmte Navigation (sie hat keinen uses-configuration-Eintrag) und läuft daher mit dem, was dieses Telefon hat.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Diese App führt keine Hardware- oder Softwarefunktionen auf, die sie benötigt (keine uses-feature-Einträge).",
"This app has no activities.": "Diese App hat keine Activities.",
"This app may not run commands in Termux yet.": "Diese App darf in Termux möglicherweise noch keine Befehle ausführen.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Diese App hat jetzt einen eigenen privaten ADB-Schlüssel. Tippen Sie auf die Modusanzeige für Details.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Der Code dieser App konnte nicht gelesen werden (sie hat keinen, oder die Datei ist nicht lesbar), daher lässt sich über Tracker nichts sagen.",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "Der eigene Autorisierungscode dieser App. Noch akzeptiert ihn nichts: Er wird hier für später aufbewahrt. Er wird auf diesem Smartphone erstellt, bleibt auf diesem Smartphone und lässt sich jederzeit ersetzen.",
"This app's own shell - no root, ADB or package manager.": "Die eigene Shell dieser App – ohne Root, ADB oder Paketmanager.",
"This app's own storage (private)": "Eigener Speicher der App (privat)",
"This app's own user and group id": "Die eigene Benutzer- und Gruppen-ID dieser App",
"This app’s key · 2048-bit RSA · in secure hardware": "Schlüssel dieser App · 2048-Bit-RSA · in sicherer Hardware",
"This app’s key · 2048-bit RSA · in the Android Keystore": "Schlüssel dieser App · 2048-Bit-RSA · im Android Keystore",
"This archive is view-only": "Dieses Archiv ist schreibgeschützt",
"This build": "Dieser Build",
"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "Diese Version der App enthält die Morphe-Engine nicht, daher ist das Patchen nicht verfügbar. Quellen, der Community-Finder und Downloads funktionieren weiterhin. Installiere eine Release-Version der App, um zu patchen.",
"This build of the app does not contain the Morphe engine. Install a release build.": "Diese Version der App enthält die Morphe-Engine nicht. Installiere eine Release-Version.",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "Dies kann die ADB-Verbindung trennen, die diese App nutzt, sodass Sie es von hier aus möglicherweise nicht zurückändern können.",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "Dadurch können Sie sich aus Teilen des Telefons aussperren (Bildschirm, Tastatur oder Bedienungshilfen).",
"This cannot be undone.": "Das lässt sich nicht rückgängig machen.",
"This device has not allowed this phone yet. Look at its screen and tap": "Dieses Gerät hat dieses Telefon noch nicht zugelassen. Sehen Sie auf seinen Bildschirm und tippen Sie auf",
