"This font could not be shown.": "Diese Schriftart konnte nicht angezeigt werden.",
"This is already what the phone uses.": "Das verwendet das Telefon bereits.",
"This is not a text file. Use View, or Open with…": "Das ist keine Textdatei. Verwenden Sie „Ansehen“ oder „Öffnen mit…“.",
