"This phone is not connected to its own ADB. Turn on ADB in this app's Working mode first (Working Mode button at the top), then try again.": "Dieses Telefon ist nicht mit seinem eigenen ADB verbunden. Schalten Sie zuerst ADB im Betriebsmodus dieser App ein (Schaltfläche „Betriebsmodus“ oben) und versuchen Sie es dann erneut.",
"This phone is not connected to its own ADB: turn on ADB in Working mode first.": "Dieses Telefon ist nicht mit seinem eigenen ADB verbunden: Schalte zuerst ADB im Betriebsmodus ein.",
"This phone lists no overlays.": "Dieses Telefon listet keine Overlays auf.",
