"This store needs the app build (Android bridge).": "Dieser Store erfordert den App-Build (Android-Bridge).",
"This version is not one the patches list. Patching may fail. Get a supported version with Morphe Helper, or patch anyway.": "Diese Version steht nicht in den Patches. Das Patchen kann scheitern. Hole mit Morphe Helper eine unterstützte Version oder patche trotzdem.",
