"Turning off ANGLE…": "ANGLE wird ausgeschaltet…",
"Turning on ANGLE…": "ANGLE wird eingeschaltet…",
"Turns battery saver off and asks Android for its fixed performance mode: the CPU and GPU hold a steady clock instead of ramping up and down, which gives even frame times and uses more battery and heat. Android 11 or newer.": "Schaltet den Energiesparmodus aus und bittet Android um seinen festen Leistungsmodus: CPU und GPU halten einen gleichmäßigen Takt, statt hoch- und herunterzufahren, was gleichmäßige Bildzeiten ergibt und mehr Akku und Wärme kostet. Android 11 oder neuer.",
"Turns battery saver off and, where the phone has it, adaptive battery saver on (Android turns the saver on by itself when the battery runs low). The phone's normal state.": "Schaltet den Energiesparmodus aus und, wo das Telefon ihn hat, den adaptiven Energiesparmodus an (Android schaltet den Sparmodus von selbst ein, wenn der Akku knapp wird). Der normale Zustand des Telefons.",
"Tweaks and controls that Android hides": "Einstellungen und Steuerungen, die Android versteckt",
"Two-button navigation bar": "Zwei-Tasten-Navigationsleiste",
"Type": "Typ",
"Type a command": "Befehl eingeben",
"Type a command first": "Geben Sie zuerst einen Befehl ein",
"Type a command for the device and press Run. A line that starts with \"adb \" goes to adb itself (adb pull, adb forward ...).": "Geben Sie einen Befehl für das Gerät ein und tippen Sie auf „Ausführen“. Eine Zeile, die mit „adb “ beginnt, geht an adb selbst (adb pull, adb forward ...).",
"Type a command for the device and press Run. Start a line with \"adb \" to send it to adb itself (adb pull, adb forward ...). The $ button switches to adb for every line.": "Geben Sie einen Befehl für das Gerät ein und tippen Sie auf „Ausführen“. Beginnen Sie eine Zeile mit „adb “, um sie an adb selbst zu senden (adb pull, adb forward ...). Die Schaltfläche $ wechselt für jede Zeile zu adb.",
"Type a host name first.": "Geben Sie zuerst einen Hostnamen ein.",
"Type a number between −1 and 1, like −0.3 or 0.5.": "Gib eine Zahl zwischen −1 und 1 ein, etwa −0,3 oder 0,5.",
"Type a number of 0 or more, like 0.5 or 1.": "Gib eine Zahl ab 0 ein, etwa 0,5 oder 1.",
"Type a whole number, like 280": "Geben Sie eine ganze Zahl ein, z. B. 280",
"Type an app name or package name.": "App-Name oder Paketname eingeben.",
"Type in the search box to find a word anywhere in the guide. This guide is in English.": "Geben Sie im Suchfeld ein Wort ein, um es überall in der Anleitung zu finden. Diese Anleitung ist auf Englisch.",
"Type it like 450x450": "Geben Sie es so ein: 450x450",
"Type something to search for.": "Gib einen Suchbegriff ein.",
"Type text (use %s for spaces)": "Text eingeben (%s für Leerzeichen verwenden)",
"Type the address and port, like 192.168.1.20:37215": "Geben Sie Adresse und Port ein, z. B. 192.168.1.20:37215",
"Type the address and port, like 192.168.1.20:5555": "Geben Sie Adresse und Port ein, z. B. 192.168.1.20:5555",
