"What the phone is doing right now: memory, storage and battery, with the model and software underneath. Reads only, nothing changes.": "Was das Telefon gerade tut: Arbeitsspeicher, Speicher und Akku, darunter Modell und Software. Nur lesen, nichts wird geändert.",
