"What this tab does when a device you were connected to drops (Wi-Fi, Wireless debugging and Bluetooth devices; a cable is never retried on its own)": "Was dieser Tab tut, wenn ein verbundenes Gerät die Verbindung verliert (Geräte über Wi-Fi, Kabelloses Debugging und Bluetooth; ein Kabel wird nie von selbst neu versucht)",
"What you took out in Details is kept.": "Was du in Details herausgenommen hast, bleibt erhalten.",
