"When a Wi-Fi sign-in page is found (0 ignore, 1 ask, 2 avoid the network)": "Wenn eine Wi-Fi-Anmeldeseite gefunden wird (0 ignorieren, 1 fragen, 2 Netzwerk meiden)",
"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Beim Löschen von Duplikaten entscheidet SD Maid, welche Datei bleibt, indem es jedes Kriterium der Reihe nach prüft. Das erste Kriterium mit einem klaren Gewinner bestimmt das Ergebnis. Zum Umsortieren ziehen, zum Ändern des Modus tippen.",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "Wenn die gewählte Quelle die Version nicht hat oder nicht funktioniert, gehen „Diese Version“, „Neueste“ und „Alle Versionen“ mit der nächsten Quelle in der obigen Reihenfolge weiter, bis eine liefert.",
"Where the tabs are. The bottom bar holds the tabs you pin and a More button for the rest; the top bar holds all of them.": "Wo die Tabs sind. Die untere Leiste zeigt die angehefteten Tabs und eine Schaltfläche „Mehr“ für den Rest; die obere Leiste zeigt alle.",
"Where the whole palette comes from": "Woher die gesamte Palette stammt",
"Where to search": "Wo suchen",
"Which apps to run the command on": "Auf welchen Apps der Befehl ausgeführt werden soll",
"Which backend performs the install": "Welches Backend die Installation durchführt",
"Which version Fast mode looks for: the one the patches need, or the newest.": "Welche Version der Schnellmodus sucht: die, die die Patches brauchen, oder die neueste.",
"Whoever gets this file can sign apps as you, and Android will install them as updates of the apps you patched here. Send it only to a place that only you can open.": "Wer diese Datei bekommt, kann Apps in deinem Namen signieren, und Android installiert sie als Updates der hier gepatchten Apps. Sende sie nur an einen Ort, den nur du öffnen kannst.",
