"Wireless debugging is not announcing this device. Turn Wireless debugging off and on on the device (same Wi-Fi), then try again.": "Wireless Debugging macht dieses Gerät nicht bekannt. Schalte Wireless Debugging am Gerät aus und wieder ein (gleiches WLAN) und versuche es erneut.",
"Withdraw consent": "Einwilligung widerrufen",
"Without it AppCleaner still deletes every cache it can reach with file access and, with a working mode, trims the caches of all apps at once.": "Ohne ihn löscht AppCleaner trotzdem jeden Cache, den er per Dateizugriff erreicht, und leert mit einem Betriebsmodus die Caches aller Apps auf einmal.",
