"Write Secure Settings": "Secure-Einstellungen schreiben",
"Write an absolute path, like /storage/emulated/0/DCIM": "Schreibe einen absoluten Pfad, z. B. /storage/emulated/0/DCIM",
"Write at least one number of seconds, like 0, 8, 25.": "Schreibe mindestens eine Sekundenzahl, z. B. 0, 8, 25.",
"Write the name segments, like DCIM/Camera": "Schreibe die Namenssegmente, z. B. DCIM/Camera",
"Write the starter ~/.bashrc": "Die Start-~/.bashrc schreiben",
"Write the starter ~/.nanorc": "Die Start-~/.nanorc schreiben",
"Write the starter ~/.vimrc": "Die Start-~/.vimrc schreiben",
"Write your message first.": "Schreibe zuerst deine Nachricht.",
"Writes everything that is waiting to be written, then tells the kernel to free the page cache and the folder and inode caches. Apps are not touched. The phone may feel slower for a moment while the caches fill again; the freed RAM is mostly a short-lived gain.": "Schreibt alles, was auf das Schreiben wartet, und sagt dann dem Kernel, den Seiten-Cache sowie die Ordner- und Inode-Caches freizugeben. Apps werden nicht angerührt. Das Telefon kann sich kurz langsamer anfühlen, während sich die Caches wieder füllen; das freigegebene RAM ist meist ein kurzlebiger Gewinn.",
"Writes pending data, then frees the file, folder and inode caches.": "Schreibt ausstehende Daten und gibt dann Datei-, Ordner- und Inode-Caches frei.",
"Written into Android as a color overlay, which only Root can do. Apply writes it along with the theme.": "Wird als Farb-Overlay in Android geschrieben, was nur Root kann. Anwenden schreibt es zusammen mit dem Design.",
"XAPK": "XAPK",
"Xiaomi": "Xiaomi",
"Xiaomi GetApps": "Xiaomi GetApps",
"Yellow": "Gelb",
"Yes": "Ja",
"You are on mobile data": "Sie nutzen mobile Daten",
"You can grant or revoke it here.": "Sie können sie hier gewähren oder widerrufen.",
"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "Sie haben dieses APK bearbeitet, daher ist seine Signatur nicht mehr gültig und Android installiert es nicht unverändert.",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "Du erklärst einer Person, die kein Entwickler ist, eine versteckte Android-Einstellung (einen Eintrag der Datenbank Settings.Global, Settings.Secure oder Settings.System, die „settings get/put“ liest und schreibt).",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "Du erklärst einer Person, die kein Entwickler ist, eine versteckte Android-Einstellung (einen Eintrag der Datenbank Settings.Global, Settings.Secure oder Settings.System, die „settings get/put“ liest und schreibt). Sag kurz: was sie steuert, was ihre Werte bedeuten, was eine Änderung bewirkt und ob sie sich gefahrlos ändern lässt. Sag klar, wenn du die Einstellung nicht kennst (viele gehören dem Telefonhersteller), statt zu raten, und sag dann, was ihr Name nahelegt. Kurze Absätze, keine Überschriften.",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "Du erklärst einer Person, die kein Entwickler ist, einen Android-Logcat-Eintrag. Sag in einfachen Worten und kurz: was diese Zeile bedeutet,",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "Du erklärst einer Person, die kein Entwickler ist, einen Android-Logcat-Eintrag. Sag in einfachen Worten und kurz: was diese Zeile bedeutet, die wahrscheinlichste Ursache, ob sie eine Rolle spielt (harmloses Rauschen, ein echtes Problem oder ein Absturz) und, falls ja, was man versuchen kann. Nutze kurze Absätze, keine Überschriften. Wenn die Zeile zu kryptisch ist, um sie sicher zu erklären, sag das und sag, was sonst helfen würde. Erfinde keine Details.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "Sie helfen bei der Syntax von ADB- und Shell-Befehlen in einem Android-Terminal. Antworten Sie kurz und praktisch.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "Sie helfen bei der Syntax von ADB- und Shell-Befehlen in einem Android-Terminal. Antworten Sie kurz und praktisch. Wenn Sie dem Nutzer genau einen Befehl vorschlagen möchten, den er hier ausführen soll, setzen Sie ihn allein in",
"You're on a metered connection (mobile data / hotspot).": "Sie nutzen eine getaktete Verbindung (mobile Daten / Hotspot).",
"Your color": "Deine Farbe",
"Your email app is open: tap send there": "Deine E-Mail-App ist offen: Tippe dort auf Senden",
"Your host name": "Dein Hostname",
"Your message": "Deine Nachricht",
"Your own number": "Ihre eigene Nummer",
"Your phone first looks up each service’s name with the DNS it uses now (once). Then each service may receive up to three short encrypted connections, each asking for example.com. ICMP ping is not available to apps, so the times are for the encrypted connection Private DNS actually uses.": "Dein Telefon sucht zuerst den Namen jedes Dienstes mit dem DNS, das es gerade nutzt (einmal). Danach erhält jeder Dienst bis zu drei kurze verschlüsselte Verbindungen, jeweils mit einer Abfrage von example.com. Ein ICMP-Ping ist für Apps nicht möglich, deshalb gelten die Zeiten für die verschlüsselte Verbindung, die Privates DNS tatsächlich nutzt.",
"Your phone was updated.": "Ihr Telefon wurde aktualisiert.",
"Your root manager was not found by its usual name (it may be installed under a different name). If it lists an app only after the app has asked for su, tap Request Super User first and allow this app when it asks. Otherwise open it yourself, allow this app, then tap Request Super User.": "Ihr Root-Manager wurde unter seinem üblichen Namen nicht gefunden (er ist vielleicht unter einem anderen Namen installiert). Führt er eine App erst auf, nachdem sie su angefragt hat, tippen Sie zuerst auf „Superuser anfordern“ und erlauben Sie diese App, wenn er fragt. Andernfalls öffnen Sie ihn selbst, erlauben diese App und tippen dann auf „Superuser anfordern“.",
"Your root manager was not found by its usual name (it may be hidden or renamed). Open it from your home screen and manage apps in its Super User list.": "Dein Root-Manager wurde unter seinem üblichen Namen nicht gefunden (er ist vielleicht versteckt oder umbenannt). Öffne ihn über den Startbildschirm und verwalte die Apps in seiner Super-User-Liste.",
"Yours stay. A list that is already here is skipped; one with the same name but other apps comes in as \"Name (imported)\".": "Deine bleiben. Eine Liste, die schon da ist, wird übersprungen; eine mit gleichem Namen, aber anderen Apps, kommt als „Name (importiert)“ dazu.",
