"The family's old folder could not be moved aside.": "Der alte Ordner der Familie konnte nicht beiseitegeschoben werden.",
"The iOS emoji file at its address is not the expected one, so its sample was not read. Update the app.": "Die iOS-Emoji-Datei unter ihrer Adresse ist nicht die erwartete, daher wurde ihr Beispiel nicht gelesen. Aktualisieren Sie die App.",
