"Thin": "Dünn",
"This family has colour glyphs. Make a font needs a plain text font, so this one may not work there.": "Diese Familie hat farbige Glyphen. „Schriftart erstellen“ braucht eine einfache Textschriftart, daher funktioniert diese dort eventuell nicht.",
"This family is larger than the app downloads (160 MB or 64 files).": "Diese Familie ist größer als das Download-Limit der App (160 MB oder 64 Dateien).",
"This family is no longer on Google Fonts, so it cannot be downloaded again. Save to phone first to keep a copy.": "Diese Familie ist nicht mehr auf Google Fonts und kann daher nicht erneut heruntergeladen werden. Tippen Sie zuerst auf „Auf Telefon speichern“, um eine Kopie zu behalten.",
"This family is no longer on Google Fonts. Its downloaded files still work here.": "Diese Familie ist nicht mehr auf Google Fonts. Ihre heruntergeladenen Dateien funktionieren hier weiterhin.",
"This family is not in the Google Fonts list. Update the list and try again.": "Diese Familie ist nicht in der Google-Fonts-Liste. Aktualisieren Sie die Liste und versuchen Sie es erneut.",
"This family's files changed on the phone. Delete it and download it again.": "Die Dateien dieser Familie haben sich auf dem Telefon geändert. Löschen Sie sie und laden Sie sie erneut herunter.",
"This font family is already downloading.": "Diese Schriftfamilie wird bereits heruntergeladen.",
"This font family is being saved. Wait for it to finish.": "Diese Schriftfamilie wird gerade gespeichert. Warten Sie, bis der Vorgang abgeschlossen ist.",
"This font family is downloading. Cancel it first.": "Diese Schriftfamilie wird heruntergeladen. Brechen Sie den Download zuerst ab.",
"This is a symbol family. Make a font needs a plain text font, so this one may not work there.": "Dies ist eine Symbolfamilie. „Schriftart erstellen“ braucht eine einfache Textschriftart, daher funktioniert diese dort eventuell nicht.",
